def transform(grid):
    """Intersect the two binary panels on either side of the colored divider."""
    div_col = next(c for c in range(len(grid[0]))
                   if all(row[c] == grid[0][c] and grid[0][c] != 0 for row in grid))
    left = [row[:div_col] for row in grid]
    right = [row[div_col + 1:] for row in grid]
    if any(len(a) != len(b) for a, b in zip(left, right)):
        raise ValueError("panels have different widths")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(r1, r2)]
            for r1, r2 in zip(left, right)]
